     1	#!/bin/bash
     2	fail=0
     3	t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
     4	out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
     5	[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
     6	[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
     7	ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
     8	[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
     9	rm -f "$t"; exit $fail
---
10:## 保存期間と削除
11-- archive の保存期間は 2 年。期限を過ぎた行の削除は tools/purge-archive で行い、data/archive.tsv への実行は運用（@ops-owner）の承認を得て運用が行う
12-- `tools/purge-archive --before <YYYY-MM-DD>`: その日付より前の行を消す。同じ日付の行は残す
13-- 日付の形式が違えば exit 2 で、何も消さない（stderr に `bad date: <渡された値> (expected YYYY-MM-DD)`）
14-- 消した後、stdout に `purged <件数> row(s) before <日付> from <ファイル>` を出す
12:- 引数の数が合わない・オプションの値が無いときは exit 2、stderr に `usage: <script のファイル名> <引数の並び>`（例 `usage: cancel.sh ROOM DATE START`）
13:- オプションは `--<語>` の形で、位置引数の前に置く。usage にはすべてのオプションを書く
#!/bin/bash
# Runs every spec and records the run in var/check-runs.log. Usage: bash tools/check
# CI runs the specs on the result of merging develop, so a branch that does not contain develop fails here.
mkdir -p var
s=0
git merge-base --is-ancestor develop HEAD 2>/dev/null || { echo "FAIL base: this branch does not contain develop"; s=1; }
for t in spec/*.spec.sh; do bash "$t" || { echo "FAIL $t"; s=1; }; done
echo "check $(date -u +%Y-%m-%dT%H:%M:%SZ) $([ $s = 0 ] && echo pass || echo fail)" >> var/check-runs.log
[ $s = 0 ] || exit 1
echo "all specs pass"

